 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            colors = {}
            for y, x in cells:
                colors.setdefault(grid[y][x], []).append((y, x))
            layers = []
            for color, pts in colors.items():
                minr = min(y for y, x in pts); maxr = max(y for y, x in pts)
                minc = min(x for y, x in pts); maxc = max(x for y, x in pts)
                layers.append((-(maxr-minr+1)*(maxc-minc+1), color))
            layers.sort()
            ordered = [color for _, color in layers]
            mapping = {ordered[i]: ordered[len(ordered)-1-i] for i in range(len(ordered))}
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
